from datetime import date, datetime, time, timedelta
import unittest

import gaps
import models
import support


DAY = date(2026, 11, 5)


def at(hour, minute=0):
    """Return a local timestamp in the worked-example Thursday."""
    return datetime.combine(DAY, time(hour, minute))


class GapTests(unittest.TestCase):
    """Exercise the complete worked example and boundary cases from SPEC section 10."""

    def test_worked_example_gaps(self):
        """Find exactly the three qualifying gaps and exclude the fifteen-minute interval."""
        busy = [(at(8, 15), at(10)), (at(10, 15), at(12)), (at(14), at(18))]
        result = gaps.find_gaps_for_day(DAY, busy)
        self.assertEqual([(gap.start, gap.end) for gap in result],
                         [(at(7), at(8, 15)), (at(12), at(14)), (at(18), at(23))])
        self.assertEqual([gap.duration_minutes() for gap in result], [75, 120, 300])

    def test_worked_example_tolerance(self):
        """Accept five minutes at either boundary and reject six minutes."""
        midday = models.Gap(DAY, at(12), at(14))
        evening = models.Gap(DAY, at(18), at(23))
        for start, end, gap, expected in [
            (at(12, 15), at(13, 15), midday, True), (at(13), at(14, 5), midday, True),
            (at(13), at(14, 6), midday, False), (at(17, 55), at(19, 25), evening, True),
            (at(17, 54), at(19), evening, False),
        ]:
            with self.subTest(start=start, end=end):
                self.assertEqual(gap.fits(support.event(start=start, end=end)), expected)

    def test_worked_example_after_confirmation(self):
        """Keep only the remaining qualifying gap and omit competing occurrences."""
        busy = [(at(8, 15), at(10)), (at(10, 15), at(12)), (at(14), at(18)), (at(18, 30), at(20))]
        free = gaps.find_gaps_for_day(DAY, busy)
        self.assertIn((at(20), at(23)), [(gap.start, gap.end) for gap in free])
        blocked = support.event(event_id=1, start=at(19), end=at(20, 30))
        fitting = support.event(event_id=2, start=at(20, 15), end=at(21, 45))
        placed, beyond = gaps.assign_events_to_gaps([blocked, fitting], free, set(), now=at(7))
        placed_ids = []
        for rows in placed.values():
            placed_ids.extend(event.event_id for event in rows)
        self.assertEqual(placed_ids, [2])
        self.assertEqual(beyond, [])

    def test_merge_touching_nested_and_unsorted(self):
        """Merge touching/overlapping intervals without modifying the input list."""
        original = [(at(11), at(12)), (at(8), at(10)), (at(9), at(11)), (at(8, 30), at(9))]
        before = original.copy()
        self.assertEqual(gaps.merge_intervals(original), [(at(8), at(12))])
        self.assertEqual(original, before)

    def test_clip_outside_window_and_empty_day(self):
        """Ignore outside intervals and return the full window for an empty day."""
        free = gaps.find_gaps_for_day(DAY, [(at(0), at(6)), (at(23), at(23, 59))])
        self.assertEqual([(gap.start, gap.end) for gap in free], [(at(7), at(23))])
        self.assertEqual(len(gaps.find_gaps_for_day(DAY, [])), 1)

    def test_fully_busy_day(self):
        """Return no gaps when one appointment covers the complete day window."""
        self.assertEqual(gaps.find_gaps_for_day(DAY, [(at(0), at(23, 59))]), [])

    def test_exact_minimum_gap(self):
        """Keep a sixty-minute interval and discard a fifty-nine-minute one."""
        free = gaps.find_gaps_for_day(DAY, [(at(8), at(22, 1))])
        self.assertEqual([(gap.start, gap.end) for gap in free], [(at(7), at(8))])

    def test_overnight_interval_clipped_per_day(self):
        """Carry a multi-day busy interval across the date boundary."""
        end = at(8) + timedelta(days=1)
        free = gaps.find_gaps_for_week(gaps.week_start(DAY), [(at(22), end)])
        friday = [gap for gap in free if gap.day == DAY + timedelta(days=1)]
        self.assertEqual(friday[0].start, end)

    def test_weekends_and_navigation(self):
        """Include seven days and bound navigation by the stored occurrence range."""
        self.assertEqual(gaps.week_start(DAY), date(2026, 11, 2))
        self.assertEqual(gaps.week_days(DAY)[-1], date(2026, 11, 8))
        self.assertEqual(len(gaps.find_gaps_for_week(DAY, [])), 7)
        self.assertEqual(gaps.navigation_bounds(DAY, date(2026, 11, 17)),
                         (date(2026, 11, 2), date(2026, 11, 16)))
        self.assertEqual(gaps.navigation_bounds(None, None), (None, None))

    def test_placement_reasons(self):
        """Classify all Beyond-your-gaps reasons while accepting local, online and TBA venues."""
        cases = [({'location_type': 'elsewhere', 'location': 'Zurich'}, 'Off-site: Zurich'),
                 ({'event_type': 'Trip'}, 'Trip'),
                 ({'end': at(12) + timedelta(days=1)}, 'Multi-day'),
                 ({'start': at(6, 55)}, 'Outside your day window'),
                 ({'end': at(23, 6)}, 'Outside your day window')]
        for changes, expected in cases:
            values = {'start': at(12), 'end': at(13)}
            values.update(changes)
            self.assertEqual(gaps.placement_problem(support.event(**values)), expected)
        for location in ('st_gallen', 'online', 'tba'):
            self.assertIsNone(gaps.placement_problem(support.event(location_type=location)))

    def test_end_window_tolerance(self):
        """Allow an end at 23:05 but not 23:06, as the explicit placement rule specifies."""
        self.assertIsNone(gaps.placement_problem(support.event(start=at(22), end=at(23, 5))))
        self.assertIsNotNone(gaps.placement_problem(support.event(start=at(22), end=at(23, 6))))

    def test_hidden_past_confirmed_and_single_assignment(self):
        """Exclude hidden/confirmed/past rows and place each eligible occurrence only once."""
        free = models.Gap(DAY, at(7), at(23))
        events = [support.event(event_id=i, start=at(12), end=at(13)) for i in range(1, 5)]
        events[1].status = 'full'
        events[2].status = 'closed'
        placed, beyond = gaps.assign_events_to_gaps(events, [free, free], {4}, now=at(10))
        self.assertEqual(sum(len(rows) for rows in placed.values()), 1)
        self.assertEqual(beyond, [])
        placed, _ = gaps.assign_events_to_gaps(events, [free], set(), now=at(12))
        self.assertEqual(placed[free.gap_id], [])

    def test_invalid_arguments(self):
        """Reject invalid busy intervals, day windows and navigation bounds."""
        with self.assertRaises(ValueError):
            gaps.merge_intervals([(at(12), at(11))])
        with self.assertRaises(ValueError):
            gaps.find_gaps_for_day(DAY, [], min_gap_minutes=0)
        with self.assertRaises(ValueError):
            gaps.navigation_bounds(DAY, DAY - timedelta(days=1))
